action.command:
cd /workspace/services/ingestion && cat > test_kh_dates.mjs << 'EOF'
const fetch = globalThis.fetch;

const ELASTIC_SEARCH_URL = 'https://elastic.kulturhusetstadsteatern.se/khst-events';

const query = {
  size: 20,
  query: {
    bool: {
      must: [
        {
          range: {
            tixStartDate: {
              gte: 'now'
            }
          }
        }
      ]
    }
  },
  sort: [
    { tixStartDate: { order: 'asc' } }
  ]
};

async function test() {
  const response = await fetch(ELASTIC_SEARCH_URL + '/_search', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'User-Agent': 'EventPulse/1.0' },
    body: JSON.stringify(query)
  });

  const data = await response.json();
  console.log('Sample events with dates:');
  data.hits?.hits?.slice(0, 10).forEach((h, i) => {
    const startDate = h._source?.tixStartDate;
    console.log(`${i+1}. ${h._source?.drupalTitle?.substring(0, 40)} - ${startDate}`);
  });
}

test().catch(console.error);
EOF
node test_kh_dates.mjs

